import{test}from'node:test';import assert from'node:assert/strict';import{readFileSync}from'node:fs';import{createHash}from'node:crypto';import{obstruction}from'../scripts/freeze-corrections-bench';import{session}from'../scripts/bot-b2-harness';import{FreezeRules}from'../src/game/freeze-tag';import{tacticalState}from'../server/strategy/state';import{Vec2,Box}from'planck';
test('a frozen frog below a low platform triggers a real detour, not endless repeated hop attempts',()=>{for(const seed of[23,123,511]){const old=obstruction(true,true,seed),now=obstruction(false,true,seed);assert.equal(old.passed,null);assert.equal(old.backed,false);assert.ok(now.backed);assert.ok(now.passed!==null&&now.passed<12,JSON.stringify(now));assert.ok(now.recoveries>0);}});
