function freeze(){const s=session('freeze',5);for(let b=s.sim.world.getBodyList();b;){const next=b.getNext();if(!s.sim.frogs.some(f=>f.body===b))s.sim.world.destroyBody(b);b=next;}s.sim.world.createBody(Vec2(20,20)).createFixture(Box(20,.5));s.sim.frogs.forEach((f,i)=>f.body.setTransform(Vec2([35,5,12,20,24][i],19),0));return s;}
test('a failed rescue is cooled down rather than selected immediately again',()=>{const s=freeze(),r=s.rules as FreezeRules,c=s.cs[1];r.records[2].frozen=true;r.records[3].frozen=true;c.input(s.sim.frogs[1],0,true,false,false,s.sim,tacticalState(r.view(0)));assert.equal(c.tactics.intent,'rescue');const target=c.tactics.target!;c.navigation.stats.recoveries++;s.sim.tick=30;c.input(s.sim.frogs[1],30,true,false,false,s.sim,tacticalState(r.view(30)));assert.notEqual(c.tactics.target,target);assert.equal(c.tactics.intent,'rescue');});
test('freeze decisions stay independently phased; frozen CPUs remain immobilized and legitimate rescue contact works',()=>{const s=freeze(),r=s.rules as FreezeRules;r.records[2].frozen=true;for(let i=0;i<5;i++)s.cs[i].input(s.sim.frogs[i],0,true,r.frozen[i],false,s.sim,tacticalState(r.view(0)));assert.ok(new Set(s.cs.filter((_,i)=>!r.frozen[i]).map(c=>(c.tactics as any).next)).size>1);assert.deepEqual(s.cs[2].input(s.sim.frogs[2],1,true,true,false,s.sim,tacticalState(r.view(1))),{x:0,y:0,held:false});r.infect(1,[[1,2]]);assert.equal(r.frozen[2],false);assert.equal(r.records[1].rescues,1);});
test('transient protection feedback is removed from layout instead of reserving/removing a HUD row',()=>{const css=readFileSync('src/ui/match-chrome.css','utf8');assert.match(css,/\.game-active #infection-feedback\{position:absolute/);assert.match(css,/pointer-events:none/);});
test('the corrections preserve every unrelated approved runtime file',()=>{const m=JSON.parse(readFileSync('docs/mouse-classic-freeze-preservation.json','utf8')),hash=(s:any)=>createHash('sha256').update(s).digest('hex');for(const[p,h]of Object.entries(m.protected))assert.equal(hash(readFileSync(p)),h,p);for(const[p,r]of Object.entries(m.files)as[string,any][]){assert.equal(hash(r.original),r.beforeSha256,p);assert.equal(hash(readFileSync(p)),r.afterSha256,p);}assert.deepEqual(Object.keys(m.files).filter(p=>!p.startsWith('tests/')).sort(),['index.html','server/navigation/navigator.ts','server/strategy/tactics.ts','src/input/mouse.ts','src/ui/match-chrome.css'].sort());for(const p of['server/navigation/navigator.ts','server/strategy/tactics.ts'])assert.doesNotMatch(readFileSync(p,'utf8'),/setTransform|setLinearVelocity|applyForce|applyLinearImpulse/);});

